G=load()

def solve(g):
    h,w=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r); B=cnt.most_common(1)[0][0]
    # object: largest connected component of a non-B color
    seen=[[False]*w for _ in range(h)]
    obj=set(); best=[]
    comp=None
    for r in range(h):
        for c in range(w):
            v=g[r][c]
            if v!=B and not seen[r][c]:
                stack=[(r,c)]; cells=[]
                seen[r][c]=True
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and g[ny][nx]!=B:
                            seen[ny][nx]=True; stack.append((ny,nx))
                if len(cells)>len(best): best=cells
    obj=set(best)
    out=[row[:] for row in g]
    h_,w_=h,w
    dirs=[(1,0),(-1,0),(0,1),(0,-1)]
    for r in range(h):
        for c in range(w):
            v=g[r][c]
            if v==B or (r,c) in obj: continue
            src=v
            done=False
            for dr,dc in dirs:
                rr,cc=r+dr,c+dc
                while 0<=rr<h and 0<=cc<w and (rr,cc) not in obj and g[rr][cc]==B:
                    rr,cc=rr+dr,cc+dc
                if 0<=rr<h and 0<=cc<w and (rr,cc) in obj:
                    out[rr][cc]=src; done=True; break
    return out

